try{ ItemPickerFetcherForRepository.displayName ||= 'ItemPickerFetcherForRepository' } catch {}
try{ AssigneePicker.displayName ||= 'AssigneePicker' } catch {}
try{ AssigneeRepositoryPicker.displayName ||= 'AssigneeRepositoryPicker' } catch {}